    minio = {"region": "us-east-1", "endpoint_url": "http://minio:9000", "access_key_id": ENV["MINIO_ROOT_USER"]}
    return [
        {
            "name": "local-warehouse-postgres", "type": "postgres", "env": "dev",
            "config": {"host": "warehouse-postgres", "port": 5432, "database": "warehouse", "user": "dataq_reader", "schema": "retail", "sslmode": "disable"},
            "secret": ENV["WAREHOUSE_READER_PASSWORD"],
        },
        {
            "name": "local-mariadb", "type": "mysql", "env": "dev",
            "config": {"host": "mariadb", "port": 3306, "database": "retail", "user": "dataq_reader", "sslmode": "disable"},
            "secret": ENV["MARIADB_READER_PASSWORD"],
        },
        {
            "name": "local-trino", "type": "trino", "env": "dev",
            "config": {"host": "trino", "port": 8080, "catalog": "warehouse", "user": "dataq", "schema": "retail", "auth_type": "none", "sslmode": "disable"},
            "secret": None,
        },
        {
            "name": "local-minio-landing", "type": "s3", "env": "dev",
            "config": {"bucket": "landing", **minio},
            "secret": ENV["MINIO_ROOT_PASSWORD"],
        },
        {
            "name": "local-azurite-landing", "type": "adls", "env": "dev",
            "config": {"account_url": f"http://azurite:10000/{ENV['AZURITE_ACCOUNT_NAME']}", "container": "landing", "auth_type": "sas"},
            "secret": azurite_sas(),
